-- ===========================================================================
-- CENSUS: hosted object census for 0213-0246 (S0a window read; S1 pass re-read)
-- W-2 (1035-ROLLOUT-PACKAGE-FINAL.md 5.1): the single-SELECT form of
-- insurance/1035-HOSTED-OBJECT-CENSUS.sql (sha256 bef4d9d8...). The 34 per-version
-- rows are byte-identical to that file; its trailing second statement (G10) is
-- dropped because machines/window-reads/g10-constraint-names.sql is the G10 read
-- (same 7 table/constraint pairs, one row per constraint).
--
-- RUN ONLY VIA: run-window-read.sh <this file>
-- One SELECT over pg_catalog and information_schema only. Counts per version;
-- no table data, no identifiers.
--
-- P-2 (amended 0214 a8bdcefe...): the 0214 row counts 30 objects, adding the three functions
-- initialize_studio_payment_jurisdiction_from_history, studio_account_acceptable_for_jurisdiction
-- and studio_named_stripe_accounts. All other rows are unchanged from census-0213-0246.sql (9f558064...).
--
-- NO 0212 CHAIN GUARD, on purpose: the S1 pass re-reads this census after the
-- apply (expected present_now = objects_checked), when history max is 0246.
--
-- EXPECTED PASS (S0a, hosted at 0212): 34 rows, versions 0213..0246, and
--   present_now = 0 on every row.
-- EXPECTED PASS (S1, after 0246): present_now = objects_checked on every row.
-- STOP CONDITION (S0a): present_now > 0 on any row, or any error.
-- ===========================================================================
select c.version, c.objects_checked, c.present_now
from (
select '0213' as version, 10 as objects_checked, (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('platform_lead_alerts')) + (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('platform_lead_alerts_guard','record_platform_demo_request','record_platform_early_access_signup','claim_platform_lead_alert','freeze_platform_lead_alert_message','settle_platform_lead_alert','expire_platform_lead_alerts','record_platform_lead_alerts_unconfigured','requeue_platform_lead_alert')) as present_now
