_namespace n on n.oid=c.relnamespace where n.nspname='public' and (c.relname,k.conname) in (('studio_payment_settings','studio_payment_settings_account_country_check'),('studio_payment_settings','studio_payment_settings_account_default_currency_check'),('studio_payment_settings','studio_payment_settings_account_observation_check'),('studio_payment_settings','studio_payment_settings_account_country_conflict_check'),('stripe_account_provisioning_attempts','stripe_account_provisioning_attempts_payment_country_check'))) as present_now
